-- KaamSetu initial PostgreSQL schema (apply only to the dedicated KaamSetu Neon database)
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE account_status AS ENUM ('pending','active','suspended','closed');
CREATE TYPE provider_status AS ENUM ('draft','submitted','approved','rejected','suspended');
CREATE TYPE booking_status AS ENUM ('requested','accepted','rejected','scheduled','in_progress','completed','cancelled','disputed');
CREATE TYPE payment_status AS ENUM ('created','pending','succeeded','failed','refunded','partially_refunded');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_subject text UNIQUE NOT NULL, email text UNIQUE, phone text UNIQUE, full_name text NOT NULL, status account_status NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('customer','provider_owner','provider_employee','super_admin','operations_admin','finance_admin','support_admin','marketing_admin')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role));
CREATE TABLE addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), label text, line1 text NOT NULL, line2 text, city text NOT NULL, state text NOT NULL, postal_code varchar(6) NOT NULL CHECK (postal_code ~ '^[0-9]{6}$'), latitude numeric(9,6), longitude numeric(9,6), is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES users(id), business_name text NOT NULL, slug text UNIQUE NOT NULL, description text, phone text NOT NULL, email text, gstin text, status provider_status NOT NULL DEFAULT 'draft', verification_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES provider_businesses(id), document_type text NOT NULL, storage_key text NOT NULL, review_status text NOT NULL DEFAULT 'pending' CHECK (review_status IN ('pending','approved','rejected')), reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, slug text NOT NULL UNIQUE, icon_key text, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE subcategories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES categories(id), name text NOT NULL, slug text NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true, UNIQUE(category_id,name));
CREATE TABLE provider_services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES provider_businesses(id), subcategory_id uuid NOT NULL REFERENCES subcategories(id), title text NOT NULL, description text, base_price_paise bigint CHECK (base_price_paise >= 0), pricing_type text NOT NULL DEFAULT 'quote' CHECK (pricing_type IN ('fixed','starting_at','quote')), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES provider_businesses(id), postal_code varchar(6) NOT NULL CHECK (postal_code ~ '^[0-9]{6}$'), city text NOT NULL, state text NOT NULL, UNIQUE(provider_id,postal_code));
CREATE TABLE provider_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES provider_businesses(id), user_id uuid NOT NULL REFERENCES users(id), job_title text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,user_id));
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_code text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES users(id), provider_id uuid NOT NULL REFERENCES provider_businesses(id), service_id uuid NOT NULL REFERENCES provider_services(id), address_id uuid NOT NULL REFERENCES addresses(id), scheduled_at timestamptz, customer_note text, quoted_amount_paise bigint CHECK (quoted_amount_paise >= 0), final_amount_paise bigint CHECK (final_amount_paise >= 0), status booking_status NOT NULL DEFAULT 'requested', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE booking_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), old_status booking_status, new_status booking_status NOT NULL, changed_by uuid NOT NULL REFERENCES users(id), note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE booking_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), employee_id uuid NOT NULL REFERENCES provider_employees(id), assigned_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(booking_id,employee_id));
CREATE TABLE subscription_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, monthly_price_paise bigint NOT NULL CHECK(monthly_price_paise >= 0), employee_limit integer NOT NULL, monthly_enquiry_limit integer NOT NULL, features jsonb NOT NULL DEFAULT '{}', is_active boolean NOT NULL DEFAULT true);
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES provider_businesses(id), plan_id uuid NOT NULL REFERENCES subscription_plans(id), status text NOT NULL CHECK(status IN ('trialing','active','past_due','cancelled','expired')), starts_at timestamptz NOT NULL, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payer_user_id uuid NOT NULL REFERENCES users(id), provider_id uuid REFERENCES provider_businesses(id), booking_id uuid REFERENCES bookings(id), subscription_id uuid REFERENCES subscriptions(id), purpose text NOT NULL CHECK(purpose IN ('subscription','booking','setup','featured_listing','refund_adjustment')), amount_paise bigint NOT NULL CHECK(amount_paise > 0), currency char(3) NOT NULL DEFAULT 'INR', status payment_status NOT NULL DEFAULT 'created', gateway text, gateway_order_id text UNIQUE, gateway_payment_id text UNIQUE, idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commission_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, rate_bps integer NOT NULL CHECK(rate_bps BETWEEN 0 AND 10000), applies_to text NOT NULL DEFAULT 'completed_booking', is_active boolean NOT NULL DEFAULT true, starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz);
CREATE TABLE commission_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES bookings(id), provider_id uuid NOT NULL REFERENCES provider_businesses(id), gross_amount_paise bigint NOT NULL CHECK(gross_amount_paise >= 0), rate_bps integer NOT NULL CHECK(rate_bps BETWEEN 0 AND 10000), commission_amount_paise bigint NOT NULL CHECK(commission_amount_paise >= 0), status text NOT NULL CHECK(status IN ('pending','earned','reversed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES bookings(id), customer_id uuid NOT NULL REFERENCES users(id), provider_id uuid NOT NULL REFERENCES provider_businesses(id), rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text, moderation_status text NOT NULL DEFAULT 'visible', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL REFERENCES users(id), booking_id uuid REFERENCES bookings(id), subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_provider_services_subcategory ON provider_services(subcategory_id) WHERE is_active;
CREATE INDEX idx_service_areas_postal_code ON service_areas(postal_code);
CREATE INDEX idx_bookings_customer_created ON bookings(customer_id,created_at DESC);
CREATE INDEX idx_bookings_provider_status ON bookings(provider_id,status,created_at DESC);
CREATE INDEX idx_payments_status_created ON payments(status,created_at DESC);
CREATE INDEX idx_audit_logs_entity ON audit_logs(entity_type,entity_id,created_at DESC);
